const entry = msg.payload;

msg.payload = {
    id:        entry.id,
    text:      entry.text             || "",
    timestamp: entry.timeCreated,
    author:    entry.loggedByFullName || "",
    files:     entry.files            || [],
    labels:    entry.labels           || []
};

return msg;

const entry = msg.payload;

const isLocation = entry.location === true;
let text = entry.content || "";
let geo = null;

if (isLocation) {
    try {
        const geojson = JSON.parse(entry.content);
        const [lng, lat] = geojson.geometry.coordinates;
        geo = { lat, lng };
        text = `Posisjon delt: https://www.google.com/maps?q=${lat}%2C${lng}`;
    } catch (e) {
        text = entry.content || "";
    }
}

msg.payload = {
    id: entry.id,
    text: text,
    timestamp: new Date(entry.createdAt).getTime(),
    author: entry.username || "",
    files: entry.files || [],
    labels: []
};

msg.geo = geo;
msg.isLocation = isLocation;

return msg;

msg.bridgeEntry = msg.payload;

var lat = msg.geo.lat;
var lng = msg.geo.lng;
msg.url = "https://maps.geoapify.com/v1/staticmap?style=osm-bright&width=600&h
eight = 400 & center=lonlat: " + lng + ", " + lat + " & zoom=15 & marker=lonlat: " + lng
  + "," + lat + ";color:%23ff0000;size:large&apiKey=DEMO";

return msg;

const tmpIn = `/tmp/map_${Date.now()}.png`;
const tmpOut = `/tmp/map_${Date.now()}.jpg`;

msg.tmpIn = tmpIn;
msg.tmpOut = tmpOut;

fs.writeFileSync(tmpIn, msg.payload);

msg.payload = `-y -i ${tmpIn} -q:v 8 -vf scale=800:-1 ${tmpOut}`;

return msg;

var compressed = fs.readFileSync(msg.tmpOut);

try { fs.unlinkSync(msg.tmpIn); } catch (e) { }
try { fs.unlinkSync(msg.tmpOut); } catch (e) { }

msg.payload = msg.bridgeEntry;
msg.payload.files = [{
    name: "location_" + Date.now() + ".jpg",
    type: "image/jpeg",
    buffer: compressed
}];

delete msg.bridgeEntry;
delete msg.tmpIn;
delete msg.tmpOut;
delete msg.geo;
delete msg.isLocation;

return msg;
